 2	
 3	const TRANSITIONS: Record<ComplaintStatus, ComplaintStatus[]> = {
 4	  REPORTED: ['ROUTING_PENDING', 'UNDER_REVIEW', 'REJECTED'],
 5	  ROUTING_PENDING: ['UNDER_REVIEW', 'REJECTED'],
 6	  UNDER_REVIEW: ['ASSIGNED', 'REJECTED', 'ROUTING_PENDING'],
 7	  ASSIGNED: ['ACCEPTED', 'ASSIGNED', 'UNDER_REVIEW', 'REJECTED'],
 8	  ACCEPTED: ['IN_PROGRESS', 'ASSIGNED'],
 9	  IN_PROGRESS: ['ON_HOLD', 'RESOLVED', 'ASSIGNED'],
10	  ON_HOLD: ['IN_PROGRESS', 'ASSIGNED', 'REJECTED'],
11	  RESOLVED: ['CITIZEN_VERIFICATION', 'REOPENED'],
12	  CITIZEN_VERIFICATION: ['CLOSED', 'REOPENED'],
13	  CLOSED: [],
14	  REJECTED: ['UNDER_REVIEW', 'REOPENED'],
15	  REOPENED: ['UNDER_REVIEW'],
16	};
17	
18	export function canTransition(from: ComplaintStatus, to: ComplaintStatus): boolean {
19	  return TRANSITIONS[from].includes(to);
20	}
21	
22	export function assertTransition(from: ComplaintStatus, to: ComplaintStatus): void {
23	  if (!canTransition(from, to)) {
24	    throw new InvalidTransitionError(from, to);
25	  }
26	}
27	
28	export class InvalidTransitionError extends Error {
29	  constructor(
30	    public readonly from: ComplaintStatus,
31	    public readonly to: ComplaintStatus,
32	  ) {
33	    super(`Invalid complaint status transition: ${from} → ${to}`);
34	    this.name = 'InvalidTransitionError';
35	  }
36	}
37	
38	const ROLE_TRANSITIONS: Partial<Record<Role, Partial<Record<ComplaintStatus, ComplaintStatus[]>>>> =
