20	  if (file.size > MAX_BYTES) throw new ValidationError('Image must be 5MB or smaller');
21	  const detected = await fileTypeFromBuffer(file.buffer);
22	  if (!detected || !ALLOWED.has(detected.mime)) {
23	    throw new ValidationError('Only JPEG, PNG, and WebP images are allowed');
24	  }
25	
26	  const complaint = await loadAuthorizedComplaint(actor, complaintId);
27	  if (actor.role === 'CITIZEN' && complaint.citizenId !== actor.id) throw new ForbiddenError();
28	
29	  const processed = await sharp(file.buffer)
30	    .rotate()
31	    .resize({ width: 1600, height: 1600, fit: 'inside', withoutEnlargement: true })
32	    .jpeg({ quality: 82 })
33	    .toBuffer();
34	
35	  const key = `complaints/${complaint.id}/${Date.now()}-${kind}.jpg`;
36	  const storage = createStorage(env);
37	  await storage.put(key, processed, 'image/jpeg');
38	
39	  return prisma.complaintMedia.create({
40	    data: {
41	      complaintId: complaint.id,
42	      uploadedById: actor.id,
43	      kind,
44	      storageKey: key,
45	      mimeType: 'image/jpeg',
46	      byteSize: processed.length,
47	      checksum: checksum(processed),
48	    },
49	  });
50	}
