52	export async function readMedia(env: Env, actor: Actor, mediaId: string) {
53	  const media = await prisma.complaintMedia.findUnique({ where: { id: mediaId } });
54	  if (!media) throw new ValidationError('Media not found');
55	  await loadAuthorizedComplaint(actor, media.complaintId);
56	  const storage = createStorage(env);
57	  const bytes = await storage.get(media.storageKey);
58	  return { bytes, mimeType: media.mimeType };
59	}

