 4	describe('complaint status machine', () => {
 5	  it('allows the happy path', () => {
 6	    expect(canTransition('REPORTED', 'UNDER_REVIEW')).toBe(true);
 7	    expect(canTransition('UNDER_REVIEW', 'ASSIGNED')).toBe(true);
 8	    expect(canTransition('ASSIGNED', 'ACCEPTED')).toBe(true);
