12	    expect(canTransition('CITIZEN_VERIFICATION', 'CLOSED')).toBe(true);
13	  });
14	
15	  it('rejects illegal jumps', () => {
16	    expect(canTransition('REPORTED', 'CLOSED')).toBe(false);
17	    expect(canTransition('CLOSED', 'IN_PROGRESS')).toBe(false);
18	  });
19	
20	  it('restricts citizen transitions', () => {
21	    expect(canRoleTransition('CITIZEN', 'CITIZEN_VERIFICATION', 'CLOSED')).toBe(true);
22	    expect(canRoleTransition('CITIZEN', 'RESOLVED', 'CLOSED')).toBe(true);
23	    expect(canRoleTransition('CITIZEN', 'UNDER_REVIEW', 'ASSIGNED')).toBe(false);
24	  });
25	
26	  it('restricts worker transitions', () => {
27	    expect(canRoleTransition('FIELD_WORKER', 'ASSIGNED', 'ACCEPTED')).toBe(true);
