105	              }),
106	            },
107	          ],
108	        }),
109	      });
110	      if (!res.ok) throw new Error(`openai_http_${res.status}`);
111	      const data = (await res.json()) as { choices: Array<{ message: { content: string } }> };
112	      const parsed = JSON.parse(data.choices[0]?.message.content ?? '{}');
113	      return aiClassificationSchema.parse(parsed);
114	    } finally {
115	      clearTimeout(timer);
116	    }
117	  }
118	}
