120	export function createAiProvider(env: Env): AiProvider {
121	  if (env.AI_PROVIDER === 'none') return new NoneProvider();
122	  if (env.AI_PROVIDER === 'openai' && env.AI_API_KEY) {
123	    return new OpenAiProvider(env.AI_API_KEY, env.AI_MODEL, env.AI_TIMEOUT_MS);
124	  }
125	  return new MockProvider();
